-- Colombia deep-dive ES/DE/FR translations (completing 325).
-- INSERT OR IGNORE throughout.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Clearance en tiempo real de la DIAN mediante CUFE, universal desde noviembre de 2020 -- uno de los mandatos CTC más antiguos y completos de América Latina', 'Esta página de análisis refleja la orientación pública y las noticias disponibles a principios de agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Las normas de facturación electrónica de Colombia cambian mediante resoluciones frecuentes de la DIAN; confirme los requisitos vigentes directamente con la DIAN o con un asesor fiscal local antes de basar en esta página sus decisiones de cumplimiento.', 'Colombia reconoció legalmente la factura electrónica ya en 1995 y construyó su sistema de clearance moderno a partir del Decreto 2242 de 2015, comenzando con pilotos voluntarios en 18 sectores económicos. La Resolución 000010 de 2018 de la DIAN ordenó la primera ola obligatoria -- los grandes contribuyentes -- hacia el clearance en tiempo real desde el 1 de septiembre de 2018. La Resolución 000042 de 2020 escalonó luego a los grupos de contribuyentes restantes durante 2020, con la última ola (Grupos 6-8) llegando el 1 de noviembre de 2020 y volviendo el mandato prácticamente universal para todo responsable de IVA e impuesto al consumo. Desde que se volvió universal, la DIAN ha ampliado el sistema a nuevos tipos de documentos -- la Resolución 000165 de 2023 convirtió los "documentos equivalentes" en papel (tickets POS, facturas de servicios públicos, boletos de transporte y aéreos) en documentos electrónicos validados por la DIAN, una implementación completada el 1 de noviembre de 2024 -- y lo ha refinado a nivel de procedimiento, más recientemente con la simplificación de datos del comprador de la Resolución 000202 de 2025 y un mecanismo de 2026 (Resolución 000011 de 2026) que permite a las empresas regularizar operaciones no facturadas previamente.', 'Cada factura electrónica de venta se construye como XML UBL 2.1 con extensiones propias de la DIAN, lleva una firma digital X.509 y recibe un CUFE (Código Único de Factura Electrónica) -- un hash SHA-384 de 96 caracteres con los datos clave de la factura -- además de un código QR en cualquier versión en PDF para su verificación pública a través del portal de la DIAN.', 'La cobertura es casi universal: todo responsable de IVA (régimen común), los responsables del impuesto al consumo, los contribuyentes del Régimen Simple (SIMPLE) y los grandes contribuyentes están todos dentro del alcance, tanto para ventas B2B como B2C y B2G. Solo los no responsables de IVA con ingresos inferiores a 3.500 UVT (unos 183,3 millones de COP en 2026) y un pequeño grupo de otras categorías exentas quedan fuera del mandato, y muchos de ellos pueden adoptarlo de todos modos de forma voluntaria.', 'Como el mandato ya es universal, el trabajo real y continuo para una empresa que ya factura en Colombia consiste en mantenerse al día con los refinamientos de procedimiento de la DIAN y su expansión hacia documentos afines -- documentos equivalentes, nómina electrónica y ahora RADIAN -- más que en determinar si la facturación electrónica se aplica en absoluto.', 'Colombia respalda su mandato con una estructura de cumplimiento real y escalonada: multas de formalidad bajo el artículo 652 del Estatuto Tributario, que escalan hasta la clausura temporal del establecimiento bajo el artículo 657 por no facturar en absoluto, además de la presión práctica de que los compradores pierdan su crédito de IVA y sus deducciones de costos por facturas no conformes.', 'La DIAN opera en Colombia un sistema de clearance con validación previa en tiempo real: toda Factura Electrónica de Venta debe transmitirse a la DIAN y recibir un CUFE antes de llegar al comprador, por lo que la factura solo adquiere validez legal una vez que la DIAN la ha aprobado. El mandato comenzó con los grandes contribuyentes bajo la Resolución 000010 de 2018 (1 de septiembre de 2018) y se volvió prácticamente universal para las empresas responsables de IVA e impuesto al consumo cuando la última ola de contribuyentes de la Resolución 000042 de 2020 llegó el 1 de noviembre de 2020. Desde entonces, la DIAN ha ampliado el sistema para cubrir los "documentos equivalentes electrónicos" -- tickets POS, facturas de servicios públicos y boletos de transporte/aéreos -- bajo la Resolución 000165 de 2023, una implementación completada el 1 de noviembre de 2024, y ha refinado las reglas de datos del comprador y de transmisión rural bajo la Resolución 000202 de 2025. Un mecanismo de 2026, la Resolución 000011 de 2026, permite ahora a las empresas regularizar voluntariamente operaciones no facturadas previamente mediante un código especial "20-REG". El incumplimiento conlleva consecuencias reales: una multa de formalidad del 1% del valor, con un tope de 950 UVT (artículo 652), y la clausura temporal del establecimiento de 3 a 10 días por no facturar en absoluto (artículo 657).', '🇨🇴' FROM countries WHERE name_en = 'Colombia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Echtzeit-Clearing der DIAN per CUFE, seit November 2020 universell -- eines der ältesten und vollständigsten CTC-Mandate Lateinamerikas', 'Diese Länderanalyse spiegelt öffentlich verfügbare Hinweise und Berichterstattung mit Stand Anfang August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Kolumbiens Vorschriften zur elektronischen Rechnungsstellung ändern sich durch häufige Entschließungen der DIAN; bestätigen Sie die aktuellen Anforderungen direkt bei der DIAN oder einem örtlichen Steuerberater, bevor Sie sich für Compliance-Entscheidungen auf diese Seite verlassen.', 'Kolumbien erkannte die elektronische Rechnung bereits 1995 gesetzlich an und baute sein modernes Clearing-System ab dem Decreto 2242/2015 auf, beginnend mit freiwilligen Pilotprojekten in 18 Wirtschaftssektoren. Die DIAN-Resolution 000010/2018 verpflichtete die erste Pflichtwelle -- Großsteuerpflichtige -- ab dem 1. September 2018 zum Echtzeit-Clearing. Die Resolution 000042/2020 staffelte anschließend die verbleibenden Steuerzahlergruppen im Laufe des Jahres 2020, wobei die letzte Welle (Gruppen 6-8) am 1. November 2020 folgte und das Mandat für praktisch jedes umsatz- und verbrauchsteuerpflichtige Unternehmen universell machte. Seit Erreichen der Universalität hat die DIAN das System auf neue Dokumenttypen ausgeweitet -- die Resolution 000165/2023 wandelte papierbasierte "documentos equivalentes" (Kassenbons, Versorgungsrechnungen, Personen- und Flugtickets) in vollständig elektronische, von der DIAN validierte Dokumente um, ein bis zum 1. November 2024 abgeschlossener Rollout -- und hat es verfahrenstechnisch verfeinert, zuletzt mit der vereinfachten Käuferdatenerfassung der Resolution 000202/2025 und einem 2026er-Mechanismus (Resolution 000011/2026), der Unternehmen erlaubt, zuvor nicht fakturierte Vorgänge zu regularisieren.', 'Jede elektronische Verkaufsrechnung (Factura Electrónica de Venta) wird als UBL-2.1-XML mit DIAN-spezifischen Erweiterungen erstellt, trägt eine digitale X.509-Signatur und erhält einen CUFE (Código Único de Factura Electrónica) -- einen 96-stelligen SHA-384-Hash der wichtigsten Rechnungsdaten -- sowie bei jeder PDF-Ausfertigung einen QR-Code zur öffentlichen Überprüfung über das Portal der DIAN.', 'Der Anwendungsbereich ist nahezu universell: jeder umsatzsteuerpflichtige Steuerzahler (allgemeines Regime), Zahler der nationalen Verbrauchsteuer, Steuerzahler im vereinfachten Regime (SIMPLE) und Großsteuerpflichtige sind allesamt erfasst -- gleichermaßen für B2B-, B2C- und B2G-Verkäufe. Nur nicht umsatzsteuerpflichtige Personen mit einem Einkommen unter 3.500 UVT (rund 183,3 Millionen COP im Jahr 2026) und eine kleine Liste weiterer befreiter Kategorien stehen außerhalb des Mandats, und selbst viele davon können es freiwillig übernehmen.', 'Da die Pflicht bereits universell ist, besteht die eigentliche laufende Arbeit für ein bereits in Kolumbien fakturierendes Unternehmen darin, mit den verfahrenstechnischen Verfeinerungen der DIAN und ihrer Ausweitung auf angrenzende Dokumenttypen -- gleichwertige Dokumente, elektronische Lohnabrechnung und nun RADIAN -- Schritt zu halten, statt zu klären, ob elektronische Rechnungsstellung überhaupt gilt.', 'Kolumbien untermauert sein Mandat mit einer echten, gestuften Durchsetzungsstruktur: Formfehlerbußen nach Artikel 652 des Estatuto Tributario, die sich bis zur vorübergehenden Schließung des Geschäftslokals nach Artikel 657 bei völliger Nichtausstellung steigern, zuzüglich des praktischen Drucks, dass Käufer bei nicht konformen Rechnungen ihren USt.-Vorsteuerabzug und ihre Kostenabzüge verlieren.', 'Die kolumbianische DIAN betreibt ein Echtzeit-Vorabvalidierungssystem: Jede Factura Electrónica de Venta muss an die DIAN übermittelt werden und einen CUFE erhalten, bevor sie den Käufer erreicht, wodurch die Rechnung erst nach Genehmigung durch die DIAN rechtlich gültig wird. Das Mandat begann mit Großsteuerpflichtigen nach der Resolution 000010/2018 (1. September 2018) und wurde für umsatz- und verbrauchsteuerpflichtige Unternehmen praktisch universell, als die letzte Steuerzahlerwelle der Resolution 000042/2020 am 1. November 2020 folgte. Seither hat die DIAN das System auf "documentos equivalentes electrónicos" -- Kassenbons, Versorgungsrechnungen und Personen-/Flugtickets -- unter der Resolution 000165/2023 ausgeweitet, ein bis zum 1. November 2024 abgeschlossener Rollout, und die Regeln zu Käuferdaten und ländlicher Übermittlung unter der Resolution 000202/2025 verfeinert. Ein 2026er-Mechanismus, die Resolution 000011/2026, erlaubt Unternehmen nun, zuvor nicht fakturierte Vorgänge über einen speziellen Code "20-REG" freiwillig zu regularisieren. Nichteinhaltung hat echte Folgen: eine Formfehlerbuße von 1% des Werts, gedeckelt auf 950 UVT (Artikel 652), und eine vorübergehende Schließung des Geschäftslokals von 3 bis 10 Tagen bei völliger Nichtausstellung (Artikel 657).', '🇨🇴' FROM countries WHERE name_en = 'Colombia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Clearance en temps réel de la DIAN via le CUFE, universelle depuis novembre 2020 -- l''un des mandats CTC les plus anciens et les plus complets d''Amérique latine', 'Cette analyse par pays reflète les informations publiques et l''actualité disponibles début août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les règles de facturation électronique de la Colombie évoluent au gré de résolutions fréquentes de la DIAN ; confirmez les exigences actuelles directement auprès de la DIAN ou d''un conseiller fiscal local avant de fonder toute décision de conformité sur cette page.', 'La Colombie a reconnu légalement la facture électronique dès 1995 et a construit son système de clearance moderne à partir du décret 2242 de 2015, en commençant par des projets pilotes volontaires dans 18 secteurs économiques. La résolution 000010 de 2018 de la DIAN a imposé la première vague obligatoire -- les grands contribuables -- au clearance en temps réel à partir du 1er septembre 2018. La résolution 000042 de 2020 a ensuite échelonné les groupes de contribuables restants au cours de 2020, la dernière vague (groupes 6 à 8) arrivant le 1er novembre 2020 et rendant le mandat pratiquement universel pour toute entreprise assujettie à la TVA ou à la taxe de consommation. Depuis qu''il est devenu universel, la DIAN a étendu le système à de nouveaux types de documents -- la résolution 000165 de 2023 a converti les "documents équivalents" papier (tickets de caisse, factures de services publics, billets de transport et aériens) en documents électroniques validés par la DIAN, une mise en œuvre achevée le 1er novembre 2024 -- et l''a affiné sur le plan procédural, plus récemment avec la simplification des données acheteur de la résolution 000202 de 2025 et un mécanisme de 2026 (résolution 000011 de 2026) permettant aux entreprises de régulariser des opérations non facturées antérieurement.', 'Chaque facture électronique de vente est construite en XML UBL 2.1 avec des extensions propres à la DIAN, porte une signature numérique X.509 et reçoit un CUFE (Código Único de Factura Electrónica) -- un hachage SHA-384 de 96 caractères des données clés de la facture -- ainsi qu''un code QR sur toute version PDF pour une vérification publique via le portail de la DIAN.', 'La couverture est quasi universelle : tout assujetti à la TVA (régime commun), les redevables de la taxe de consommation nationale, les contribuables du régime simplifié (SIMPLE) et les grands contribuables sont tous concernés, aussi bien pour les ventes B2B que B2C et B2G. Seuls les non-assujettis à la TVA dont les revenus sont inférieurs à 3 500 UVT (environ 183,3 millions de COP en 2026) et une courte liste d''autres catégories exonérées échappent au mandat, et beaucoup d''entre eux peuvent tout de même l''adopter volontairement.', 'Le mandat étant déjà universel, le travail réel et continu pour une entreprise facturant déjà en Colombie consiste à suivre les affinements procéduraux de la DIAN et son extension vers des documents connexes -- documents équivalents, paie électronique et désormais RADIAN -- plutôt qu''à déterminer si la facturation électronique s''applique.', 'La Colombie assortit son mandat d''une véritable structure d''application graduée : des amendes de formalité en vertu de l''article 652 de l''Estatuto Tributario, pouvant aller jusqu''à la fermeture temporaire de l''établissement en vertu de l''article 657 en cas de défaut total de facturation, ainsi que la pression pratique exercée sur les acheteurs qui perdent leur crédit de TVA et leurs déductions de coûts sur des factures non conformes.', 'La DIAN colombienne exploite un système de clearance avec validation préalable en temps réel : chaque Factura Electrónica de Venta doit être transmise à la DIAN et recevoir un CUFE avant de parvenir à l''acheteur, la facture n''acquérant une validité légale qu''une fois approuvée par la DIAN. Le mandat a débuté avec les grands contribuables en vertu de la résolution 000010 de 2018 (1er septembre 2018) et est devenu pratiquement universel pour les entreprises assujetties à la TVA et à la taxe de consommation lorsque la dernière vague de contribuables de la résolution 000042 de 2020 est arrivée le 1er novembre 2020. La DIAN a depuis étendu le système aux "documentos equivalentes electrónicos" -- tickets de caisse, factures de services publics et billets de transport/aériens -- en vertu de la résolution 000165 de 2023, une mise en œuvre achevée le 1er novembre 2024, et a affiné les règles relatives aux données acheteur et à la transmission rurale en vertu de la résolution 000202 de 2025. Un mécanisme de 2026, la résolution 000011 de 2026, permet désormais aux entreprises de régulariser volontairement des opérations non facturées antérieurement au moyen d''un code spécial "20-REG". Le non-respect entraîne des conséquences réelles : une amende de formalité de 1 % de la valeur, plafonnée à 950 UVT (article 652), et une fermeture temporaire de l''établissement de 3 à 10 jours en cas de défaut total de facturation (article 657).', '🇨🇴' FROM countries WHERE name_en = 'Colombia';

