INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato", "XML UBL 2.1 con extensiones propias de la DIAN"], ["Firma digital", "Certificado X.509 de una autoridad de certificación colombiana acreditada"], ["CUFE", "Hash SHA-384 de 96 caracteres de los datos clave de la factura, generado en la validación"], ["Código QR", "Obligatorio en las versiones en PDF, permite la verificación pública a través del portal de la DIAN"]]', 'El formato basado en UBL de Colombia está más cerca del mundo de la EN 16931 europea que el esquema XML propio de Argentina -- una ventaja práctica real para las empresas multinacionales que operan la misma plataforma de facturación en ambas regiones.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Format", "UBL-2.1-XML mit DIAN-spezifischen Erweiterungen"], ["Digitale Signatur", "X.509-Zertifikat einer akkreditierten kolumbianischen Zertifizierungsstelle"], ["CUFE", "96-stelliger SHA-384-Hash der wichtigsten Rechnungsdaten, bei der Validierung erzeugt"], ["QR-Code", "Auf PDF-Ausfertigungen vorgeschrieben, ermöglicht öffentliche Überprüfung über das Portal der DIAN"]]', 'Kolumbiens UBL-basiertes Format steht der europäischen EN-16931-Welt näher als Argentiniens eigenes XML-Schema -- ein echter praktischer Vorteil für multinationale Unternehmen, die denselben Rechnungsstack in beiden Regionen betreiben.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format", "XML UBL 2.1 avec extensions propres à la DIAN"], ["Signature électronique", "Certificat X.509 d''une autorité de certification colombienne accréditée"], ["CUFE", "Hachage SHA-384 de 96 caractères des données clés de la facture, généré lors de la validation"], ["Code QR", "Obligatoire sur les versions PDF, permettant une vérification publique via le portail de la DIAN"]]', 'Le format colombien basé sur UBL est plus proche de l''univers européen de l''EN 16931 que le schéma XML propre de l''Argentine -- un avantage pratique réel pour les entreprises multinationales exploitant la même pile de facturation dans les deux régions.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'file_format' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Identificador fiscal", "NIT (Número de Identificación Tributaria)"], ["Registro", "Inscripción ante la DIAN más un proveedor tecnológico acreditado, o el portal gratuito de facturación de la propia DIAN para pequeñas empresas que califiquen"], ["Organismo regulador", "DIAN -- Dirección de Impuestos y Aduanas Nacionales"], ["Canales de emisión", "Software de un proveedor tecnológico certificado, el portal gratuito de la DIAN, o una integración directa de sistema a sistema"]]', 'El portal gratuito de la DIAN mantiene el cumplimiento genuinamente accesible para los contribuyentes más pequeños, no solo para quienes pueden costear un software de facturación comercial.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["Steuerpflichtigen-ID", "NIT (Número de Identificación Tributaria)"], ["Registrierung", "Anmeldung bei der DIAN plus ein akkreditierter Technologieanbieter, oder das eigene kostenlose Rechnungsportal der DIAN für qualifizierte Kleinunternehmen"], ["Aufsichtsbehörde", "DIAN -- Dirección de Impuestos y Aduanas Nacionales"], ["Ausstellungskanäle", "Software eines zertifizierten Technologieanbieters, das kostenlose Portal der DIAN, oder eine direkte System-zu-System-Integration"]]', 'Das kostenlose DIAN-Portal hält die Compliance auch für die kleinsten Steuerpflichtigen tatsächlich erreichbar, nicht nur für jene, die sich kommerzielle Rechnungssoftware leisten können.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Identifiant fiscal", "NIT (Número de Identificación Tributaria)"], ["Enregistrement", "Inscription auprès de la DIAN plus un prestataire technologique accrédité, ou le portail gratuit de facturation de la DIAN elle-même pour les petites entreprises éligibles"], ["Organisme de contrôle", "DIAN -- Dirección de Impuestos y Aduanas Nacionales"], ["Canaux d''émission", "Logiciel d''un prestataire technologique certifié, portail gratuit de la DIAN, ou intégration directe système à système"]]', 'Le portail gratuit de la DIAN maintient une conformité réellement accessible pour les plus petits contribuables, pas seulement pour ceux qui peuvent s''offrir un logiciel de facturation commercial.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'file_format' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["Campos principales", "NIT del emisor/comprador, tipo de factura, fecha, ítems, desglose de IVA/INC, CUFE"], ["Desde la Resolución 000202/2025", "Las facturas POS pueden capturar solo nombre, tipo/número de identificación y correo para compradores que no estén ya en el registro de la DIAN"], ["RADIAN", "Las facturas pueden registrarse como títulos valores, habilitando el factoring mediante endosos registrados"], ["Conservación", "5 años o más, por parte del emisor y del comprador"]]', 'RADIAN es una característica genuinamente distintiva que este sitio no ha visto en ningún otro país: convertir una factura electrónica validada en un instrumento financiero negociable, no solo en un registro fiscal.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte', '[["Kernfelder", "NIT von Aussteller/Käufer, Rechnungstyp, Datum, Positionen, USt./Verbrauchsteuer-Aufschlüsselung, CUFE"], ["Seit Resolution 000202/2025", "POS-Rechnungen dürfen für Käufer, die noch nicht im DIAN-Register erfasst sind, nur Name, Ausweisart/-nummer und E-Mail erfassen"], ["RADIAN", "Rechnungen können als handelbare Wertpapiere registriert werden, was Factoring über eingetragene Indossierungen ermöglicht"], ["Aufbewahrung", "Mindestens 5 Jahre, sowohl bei Aussteller als auch Käufer"]]', 'RADIAN ist ein wirklich unverwechselbares Merkmal, das diese Seite anderswo nicht gesehen hat: Es macht aus einer validierten E-Rechnung ein handelbares Finanzinstrument, nicht nur einen Steuerbeleg.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["Champs principaux", "NIT de l''émetteur/de l''acheteur, type de facture, date, lignes, ventilation TVA/taxe de consommation, CUFE"], ["Depuis la résolution 000202/2025", "Les factures en point de vente peuvent ne recueillir que le nom, le type/numéro de pièce d''identité et l''e-mail pour les acheteurs non déjà présents dans le registre de la DIAN"], ["RADIAN", "Les factures peuvent être enregistrées comme titres négociables, permettant l''affacturage via des endossements enregistrés"], ["Conservation", "5 ans ou plus, par l''émetteur et l''acheteur"]]', 'RADIAN est une caractéristique véritablement distinctive que ce site n''a observée nulle part ailleurs : transformer une facture électronique validée en un instrument financier négociable, pas seulement en un registre fiscal.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo de facturación", "Clearance en tiempo real -- la DIAN valida y emite un CUFE, típicamente en segundos, antes de que la factura llegue al comprador"], ["Cobertura", "B2B, B2C y B2G -- prácticamente universal desde el 1 de noviembre de 2020"], ["Contingencia", "Un procedimiento sin conexión documentado, con transmisión retroactiva una vez restablecidos los sistemas"], ["Sin un CUFE válido", "La factura no tiene validez fiscal, y el comprador no puede reclamar los costos ni el crédito de IVA relacionados"]]', 'Al igual que Argentina, se trata de un verdadero modelo de clearance previo a la entrega, no de reporte posterior a la auditoría -- la factura no está legalmente completa hasta que la DIAN ya la validó.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkmodell', '[["Rechnungsmodell", "Echtzeit-Clearing -- die DIAN validiert und vergibt typischerweise binnen Sekunden einen CUFE, bevor die Rechnung den Käufer erreicht"], ["Abdeckung", "B2B, B2C und B2G -- seit dem 1. November 2020 praktisch universell"], ["Notfallverfahren", "Ein dokumentiertes Offline-Verfahren mit nachträglicher Übermittlung nach Wiederherstellung der Systeme"], ["Ohne gültigen CUFE", "Hat die Rechnung keine steuerliche Gültigkeit, und der Käufer kann die zugehörigen Kosten oder USt.-Vorsteuer nicht geltend machen"]]', 'Wie in Argentinien handelt es sich hier um ein echtes Clearing-Modell vor der Auslieferung, nicht um ein nachträgliches Meldeverfahren -- die Rechnung ist rechtlich erst vollständig, nachdem die DIAN sie bereits validiert hat.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle de facturation", "Clearance en temps réel -- la DIAN valide et délivre un CUFE, généralement en quelques secondes, avant que la facture n''atteigne l''acheteur"], ["Couverture", "B2B, B2C et B2G -- pratiquement universelle depuis le 1er novembre 2020"], ["Contingence", "Une procédure hors ligne documentée, avec transmission rétroactive une fois les systèmes rétablis"], ["Sans CUFE valide", "La facture n''a aucune validité fiscale, et l''acheteur ne peut réclamer les coûts ni le crédit de TVA associés"]]', 'Comme en Argentine, il s''agit d''un véritable modèle de clearance avant remise, non d''un reporting a posteriori -- la facture n''est légalement complète qu''une fois déjà validée par la DIAN.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Lo que realmente es obligatorio hoy', '[["Grandes contribuyentes", "Obligatorio desde el 1 de septiembre de 2018 (Resolución 000010/2018)"], ["Todas las empresas responsables de IVA/INC", "Obligatorio desde el 1 de noviembre de 2020 (Resolución 000042/2020)"], ["Documentos equivalentes (POS, servicios públicos, transporte/boletos aéreos)", "Plenamente electrónicos desde el 1 de noviembre de 2024 (Resolución 000165/2023 + 000008/2024)"], ["Exentos", "No responsables de IVA con ingresos inferiores a 3.500 UVT (~183,3 millones de COP en 2026), más una corta lista de otras categorías"]]', 'El umbral de exención es una de las pocas excepciones genuinas que quedan en este mandato -- la mayoría de las empresas colombianas por encima de un tamaño modesto no tienen forma de evitar la facturación electrónica.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was heute tatsächlich verpflichtend ist', '[["Großsteuerpflichtige", "Verpflichtend seit 1. September 2018 (Resolution 000010/2018)"], ["Alle umsatz-/verbrauchsteuerpflichtigen Unternehmen", "Verpflichtend seit 1. November 2020 (Resolution 000042/2020)"], ["Gleichwertige Dokumente (Kassenbons, Versorgungsleistungen, Personen-/Flugtickets)", "Vollständig elektronisch seit 1. November 2024 (Resolution 000165/2023 + 000008/2024)"], ["Befreit", "Nicht umsatzsteuerpflichtige Personen mit einem Einkommen unter 3.500 UVT (~183,3 Mio. COP im Jahr 2026), plus eine kurze Liste weiterer Kategorien"]]', 'Der Befreiungsschwellenwert ist eine der wenigen echten Ausnahmen, die in diesem Mandat verbleiben -- die meisten kolumbianischen Unternehmen oberhalb einer moderaten Größe haben keine Möglichkeit, der elektronischen Rechnungsstellung zu entgehen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce qui est réellement obligatoire aujourd''hui', '[["Grands contribuables", "Obligatoire depuis le 1er septembre 2018 (résolution 000010/2018)"], ["Toutes les entreprises assujetties à la TVA/taxe de consommation", "Obligatoire depuis le 1er novembre 2020 (résolution 000042/2020)"], ["Documents équivalents (tickets de caisse, services publics, transport/billets aériens)", "Entièrement électroniques depuis le 1er novembre 2024 (résolution 000165/2023 + 000008/2024)"], ["Exonérés", "Non-assujettis à la TVA dont les revenus sont inférieurs à 3 500 UVT (~183,3 millions de COP en 2026), plus une courte liste d''autres catégories"]]', 'Le seuil d''exonération est l''une des rares exceptions réelles subsistant dans ce mandat -- la plupart des entreprises colombiennes dépassant une taille modeste n''ont aucun moyen d''échapper à la facturation électronique.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'En evolución activa, no un sistema estático', '[["2023-2024", "Documentos equivalentes electrónicos implementados por fases (Resolución 000165/2023, ampliada por la 000008/2024)"], ["31 mar 2025", "Datos del comprador simplificados y ventana de transmisión rural de 48 horas (Resolución 000202/2025)"], ["23 sep 2025", "La DIAN consolidó las normas de facturación electrónica (y más de 60 otras normas tributarias) en una única resolución, la 000227/2025"], ["23 abr 2026", "Mecanismo voluntario de regularización para operaciones no facturadas previamente (Resolución 000011/2026)"]]', 'El mandato de Colombia alcanzó cobertura universal ya en 2020, pero la DIAN sigue emitiendo refinamientos genuinos de procedimiento y de alcance cada año desde entonces -- conviene tratarlo como un sistema activamente mantenido, no como un casillero marcado una sola vez en 2020.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Aktiv in Entwicklung, kein stabiles System', '[["2023-2024", "Elektronische gleichwertige Dokumente stufenweise eingeführt (Resolution 000165/2023, verlängert durch 000008/2024)"], ["31. Mär. 2025", "Vereinfachte Käuferdaten und ein 48-Stunden-Fenster für ländliche Übermittlung (Resolution 000202/2025)"], ["23. Sep. 2025", "Die DIAN konsolidierte die Regeln zur elektronischen Rechnungsstellung (und über 60 weitere Steuervorschriften) in einer einzigen Resolution, 000227/2025"], ["23. Apr. 2026", "Freiwilliger Regularisierungsmechanismus für zuvor nicht fakturierte Vorgänge (Resolution 000011/2026)"]]', 'Kolumbiens Mandat erreichte bereits 2020 universelle Abdeckung, doch die DIAN erlässt seither jedes Jahr echte verfahrenstechnische und geltungsbereichsbezogene Verfeinerungen -- es sollte als aktiv gepflegtes System behandelt werden, nicht als 2020 einmal abgehakter Punkt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'En évolution active, pas un système figé', '[["2023-2024", "Documents équivalents électroniques mis en place par étapes (résolution 000165/2023, prolongée par la 000008/2024)"], ["31 mars 2025", "Données acheteur simplifiées et fenêtre de transmission rurale de 48 heures (résolution 000202/2025)"], ["23 sept. 2025", "La DIAN a consolidé les règles de facturation électronique (et plus de 60 autres réglementations fiscales) en une résolution unique, la 000227/2025"], ["23 avr. 2026", "Mécanisme volontaire de régularisation pour les opérations non facturées antérieurement (résolution 000011/2026)"]]', 'Le mandat colombien a atteint une couverture universelle dès 2020, mais la DIAN continue d''édicter de véritables affinements procéduraux et de périmètre chaque année depuis -- il convient de le traiter comme un système activement entretenu, non comme une case cochée une fois pour toutes en 2020.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🔒 Clausura, no solo una multa, por no facturar', NULL, NULL, 'Bajo el artículo 657 del Estatuto Tributario, la DIAN puede ordenar la clausura temporal del establecimiento -- típicamente de 3 a 10 días -- por no emitir las facturas electrónicas requeridas, o la empresa puede en su lugar pagar una suma equivalente al 5% de los ingresos brutos del mes anterior para evitar la clausura. Es una consecuencia materialmente más dura que una multa fija.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🔒 Schließung statt bloßer Geldbuße bei Nichtausstellung', NULL, NULL, 'Nach Artikel 657 des Estatuto Tributario kann die DIAN eine vorübergehende Schließung des Geschäftslokals anordnen -- typischerweise 3 bis 10 Tage -- wenn die erforderlichen elektronischen Rechnungen nicht ausgestellt werden; alternativ kann das Unternehmen einen Betrag in Höhe von 5% des Bruttoumsatzes des Vormonats zahlen, um die Schließung abzuwenden. Das ist eine deutlich härtere Folge als eine feste Geldbuße.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🔒 Une fermeture, pas seulement une amende, en cas de défaut de facturation', NULL, NULL, 'En vertu de l''article 657 de l''Estatuto Tributario, la DIAN peut ordonner la fermeture temporaire de l''établissement -- généralement de 3 à 10 jours -- pour défaut d''émission des factures électroniques requises, ou l''entreprise peut à la place verser une somme égale à 5 % du chiffre d''affaires brut du mois précédent pour éviter la fermeture. C''est une conséquence nettement plus sévère qu''une amende forfaitaire.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '💳 Sin CUFE, no hay deducción', NULL, NULL, 'Una factura sin la validación adecuada de la DIAN no tiene valor de soporte fiscal: el comprador que la posee no puede reclamar la deducción de costos ni el crédito de IVA correspondiente, y la DIAN cruza activamente los datos de facturación con las declaraciones de renta y los registros de nómina electrónica para detectar brechas. La presión de mercado que esto genera suele ser un motor de cumplimiento más fuerte que las propias multas.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '💳 Kein CUFE, kein Abzug', NULL, NULL, 'Eine Rechnung ohne ordnungsgemäße DIAN-Validierung hat keinen steuerlichen Nachweiswert: Der Käufer, der sie besitzt, kann den zugehörigen Kostenabzug oder USt.-Vorsteuerabzug nicht geltend machen, und die DIAN gleicht Rechnungsdaten aktiv mit Einkommensteuererklärungen und elektronischen Lohnabrechnungsdaten ab, um Lücken zu finden. Der dadurch entstehende Marktdruck ist oft ein stärkerer Compliance-Treiber als die Geldbußen selbst.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '💳 Pas de CUFE, pas de déduction', NULL, NULL, 'Une facture sans validation DIAN adéquate n''a aucune valeur de justificatif fiscal : l''acheteur qui la détient ne peut réclamer la déduction de coûts ni le crédit de TVA correspondant, et la DIAN recoupe activement les données de facturation avec les déclarations d''impôt sur le revenu et les registres de paie électronique pour détecter les lacunes. La pression de marché ainsi créée est souvent un moteur de conformité plus fort que les amendes elles-mêmes.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🌎 Una segunda oportunidad para brechas pasadas, no una amnistía hacia adelante', NULL, NULL, 'La Resolución 000011/2026 permite a las empresas regularizar voluntariamente operaciones previamente no facturadas o facturadas de forma incorrecta, transmitiendo un documento especial "tipo 3" con el código "20-REG" -- reduciendo el riesgo fiscal por brechas pasadas genuinas sin afectar las facultades ordinarias de fiscalización de la DIAN hacia adelante.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🌎 Eine zweite Chance für vergangene Lücken, keine Amnestie für die Zukunft', NULL, NULL, 'Die Resolution 000011/2026 erlaubt Unternehmen, zuvor nicht oder fehlerhaft fakturierte Vorgänge freiwillig zu regularisieren, indem sie ein spezielles "Typ-3"-Dokument mit dem Code "20-REG" übermitteln -- wodurch das steuerliche Risiko für echte vergangene Lücken verringert wird, ohne die üblichen Durchsetzungsbefugnisse der DIAN für die Zukunft einzuschränken.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🌎 Une seconde chance pour les lacunes passées, pas une amnistie pour l''avenir', NULL, NULL, 'La résolution 000011/2026 permet aux entreprises de régulariser volontairement des opérations antérieurement non facturées ou mal facturées en transmettant un document spécial de "type 3" portant le code "20-REG" -- réduisant le risque fiscal pour de véritables lacunes passées sans affecter les pouvoirs ordinaires de contrôle de la DIAN pour l''avenir.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Colombia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'es', 'Factura emitida sin cumplir todos los requisitos legales (error de formalidad)', '1% del valor de la operación', 'Tope de 950 UVT (≈ 49,7 millones de COP en 2026)' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Colombia' AND r.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'de', 'Rechnung ohne vollständige gesetzliche Anforderungen ausgestellt (Formfehler)', '1% des Transaktionswerts', 'Gedeckelt auf 950 UVT (≈ 49,7 Mio. COP im Jahr 2026)' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Colombia' AND r.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'fr', 'Facture émise sans respecter toutes les exigences légales (erreur de formalité)', '1 % de la valeur de la transaction', 'Plafonné à 950 UVT (≈ 49,7 millions de COP en 2026)' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Colombia' AND r.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'es', 'Factura no emitida en absoluto', 'Clausura temporal del establecimiento (3-10 días), o 5% de los ingresos brutos del mes anterior en su lugar', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Colombia' AND r.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'de', 'Rechnung überhaupt nicht ausgestellt', 'Vorübergehende Schließung des Geschäftslokals (3-10 Tage), oder alternativ 5% des Bruttoumsatzes des Vormonats', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Colombia' AND r.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'fr', 'Facture non émise du tout', 'Fermeture temporaire de l''établissement (3-10 jours), ou 5 % du chiffre d''affaires brut du mois précédent à défaut', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Colombia' AND r.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Confirme que su software de facturación transmita cada factura a la DIAN para validación de CUFE en tiempo real antes de la entrega', 'Una factura sin un CUFE válido no tiene valor de soporte fiscal para ninguna de las partes -- el control más importante para cualquier empresa que ya facture en Colombia.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Stellen Sie sicher, dass Ihre Rechnungssoftware jede Rechnung vor der Auslieferung zur Echtzeit-CUFE-Validierung an die DIAN übermittelt', 'Eine Rechnung ohne gültigen CUFE hat für keine der beiden Transaktionsseiten steuerlichen Nachweiswert -- die wichtigste Prüfung für jedes Unternehmen, das bereits in Kolumbien fakturiert.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Vérifiez que votre logiciel de facturation transmette chaque facture à la DIAN pour validation CUFE en temps réel avant la remise', 'Une facture sans CUFE valide n''a aucune valeur de justificatif fiscal pour aucune des deux parties -- le contrôle le plus important pour toute entreprise facturant déjà en Colombie.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Si emite tickets POS, facturas de servicios públicos o boletos de transporte/aéreos, confirme que esté en el formato de documento equivalente plenamente electrónico', 'Esta implementación por fases se completó el 1 de noviembre de 2024 bajo la Resolución 000165/2023, ampliada por la Resolución 000008/2024 -- no queda ninguna opción en papel para las categorías estándar.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Wenn Sie Kassenbons, Versorgungsrechnungen oder Personen-/Flugtickets ausstellen, stellen Sie sicher, dass Sie das vollständig elektronische Format für gleichwertige Dokumente nutzen', 'Dieser stufenweise Rollout wurde am 1. November 2024 unter der Resolution 000165/2023, verlängert durch die Resolution 000008/2024, abgeschlossen -- für Standardkategorien bleibt keine Papieroption übrig.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Si vous émettez des tickets de caisse, des factures de services publics ou des billets de transport/aériens, vérifiez que vous êtes passé au format de document équivalent entièrement électronique', 'Cette mise en œuvre progressive s''est achevée le 1er novembre 2024 en vertu de la résolution 000165/2023, prolongée par la résolution 000008/2024 -- il ne reste aucune option papier pour les catégories standard.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Adopte el flujo simplificado de datos del comprador de la Resolución 000202/2025, y la ventana de transmisión rural de 48 horas si le corresponde', 'Los sistemas de punto de venta que aún capturan más datos del comprador de lo requerido, o los prestadores de servicios públicos en zonas de baja conectividad que aún no usan la ventana de contingencia, están rezagados respecto a la guía vigente de la DIAN.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Übernehmen Sie den vereinfachten Käuferdaten-Ablauf der Resolution 000202/2025 sowie das 48-Stunden-Fenster für ländliche Übermittlung, falls dies auf Sie zutrifft', 'Kassensysteme, die weiterhin mehr Käuferdaten als erforderlich erfassen, oder Versorgungsunternehmen in Gebieten mit schwacher Konnektivität, die das Notfallfenster noch nicht nutzen, hinken der aktuellen DIAN-Leitlinie hinterher.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Adoptez le flux simplifié de données acheteur de la résolution 000202/2025, ainsi que la fenêtre de transmission rurale de 48 heures si elle s''applique à vous', 'Les systèmes de point de vente qui collectent encore plus de données acheteur que nécessaire, ou les prestataires de services publics dans les zones à faible connectivité n''utilisant pas encore la fenêtre de contingence, sont en retard par rapport aux directives actuelles de la DIAN.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Mantenga al día las declaraciones de nómina electrónica junto con su facturación', 'La DIAN cruza los pagos laborales reportados en la nómina electrónica con los costos, deducciones y retenciones mensuales declarados -- una inconsistencia aquí atrae el mismo escrutinio que una brecha de facturación.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Halten Sie die Meldungen zur elektronischen Lohnabrechnung (nómina electrónica) parallel zu Ihrer Rechnungsstellung aktuell', 'Die DIAN gleicht in der elektronischen Lohnabrechnung gemeldete Lohnzahlungen mit erklärten Kosten, Abzügen und monatlichen Quellensteuern ab -- eine Abweichung hier zieht die gleiche Prüfung nach sich wie eine Rechnungslücke.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Maintenez à jour les déclarations de paie électronique parallèlement à votre facturation', 'La DIAN recoupe les paiements salariaux déclarés dans la paie électronique avec les coûts, déductions et retenues mensuelles déclarés -- une divergence ici attire le même examen qu''une lacune de facturation.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Si tiene brechas históricas de facturación, revise el mecanismo de regularización "20-REG" de la Resolución 000011/2026 antes de que una auditoría las descubra', 'Permite transmitir voluntariamente operaciones previamente no facturadas usando un código especial, reduciendo el riesgo fiscal -- pero no limita las facultades ordinarias de fiscalización de la DIAN hacia adelante.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Wenn Sie historische Rechnungslücken haben, prüfen Sie den "20-REG"-Regularisierungsmechanismus der Resolution 000011/2026, bevor eine Prüfung sie aufdeckt', 'Er erlaubt es, zuvor nicht fakturierte Vorgänge freiwillig mit einem speziellen Code zu übermitteln und so das steuerliche Risiko zu senken -- schränkt aber die üblichen Durchsetzungsbefugnisse der DIAN für die Zukunft nicht ein.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Si vous avez des lacunes de facturation historiques, examinez le mécanisme de régularisation "20-REG" de la résolution 000011/2026 avant qu''un contrôle ne les révèle', 'Il permet de transmettre volontairement des opérations antérieurement non facturées à l''aide d''un code spécial, réduisant le risque fiscal -- mais ne limite pas les pouvoirs ordinaires de contrôle de la DIAN pour l''avenir.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Colombia' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'es', 'DIAN -- Sistema de Facturación Electrónica' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Colombia' AND p.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'de', 'DIAN -- System der elektronischen Rechnungsstellung' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Colombia' AND p.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'DIAN -- Système de facturation électronique' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Colombia' AND p.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'es', 'DIAN -- Normativa de facturación electrónica' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Colombia' AND p.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'de', 'DIAN -- Vorschriften zur elektronischen Rechnungsstellung' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Colombia' AND p.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'DIAN -- Réglementation de la facturation électronique' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Colombia' AND p.sort_order = 1;
